rules.expression:
measure: net_amount {
    type: sum
    sql: ${net_cents} ;;
    filters: [status: "posted"]
  }

measure: paid_amount {
    type: sum
    sql: ${TABLE}.paid_cents ;;
    filters: [status: "posted"]
  }

measure: payment_rate {
    type: number
    sql: ${paid_amount} / NULLIF(${net_amount}, 0) ;;
  }
